func setupHandlers(s *Server) {
	// Pages
	s.mux.HandleFunc(
		"GET /count/{$}",
		s.handlePageCountGET)
	s.mux.HandleFunc(
		"GET /count/_$/{$}",
		s.handlePageCountGETStream)
	s.mux.HandleFunc(
		"GET /embed-only/{$}",
		s.handlePageEmbedOnlyGET)
	s.mux.HandleFunc(
		"GET /embed-only/_$/{$}",
		s.handlePageEmbedOnlyGETStream)
	s.mux.HandleFunc(
		"GET /",
		s.handlePageIndexGET)
	s.mux.HandleFunc(
		"GET /label/{$}",
		s.handlePageLabelGET)
	s.mux.HandleFunc(
		"GET /label/_$/{$}",
		s.handlePageLabelGETStream)
	s.mux.HandleFunc(
		"GET /nested/{$}",
		s.handlePageNestedGET)
	s.mux.HandleFunc(
		"GET /nested/_$/{$}",
		s.handlePageNestedGETStream)
	s.mux.HandleFunc(
		"GET /pointer/{$}",
		s.handlePagePointerGET)
	s.mux.HandleFunc(
		"GET /pointer/_$/{$}",
		s.handlePagePointerGETStream)
	s.mux.HandleFunc(
		"POST /count/bump/{$}",
		s.handlePageCountPOSTBump)
	s.mux.HandleFunc(
		"POST /label/set/{$}",
		s.handlePageLabelPOSTSet)
	s.mux.HandleFunc(
		"POST /nested/bump/{$}",
		s.handlePageNestedPOSTBump)
	s.mux.HandleFunc(
		"POST /pointer/bump/{$}",
		s.handlePagePointerPOSTBump)
}

func (s *Server) httpErrIntern(
	w http.ResponseWriter, _ *http.Request,
	_ *datastar.ServerSentEventGenerator, msg string, err error,
) {
	s.logErr(msg, err)
	switch {
	case errors.Is(err, httperr.BadRequest):
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
	case errors.Is(err, httperr.Forbidden):
		http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
	case errors.Is(err, httperr.NotFound):
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
	case errors.Is(err, httperr.Conflict):
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
	default:
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
	}
}

func (s *Server) handlePageCountGET(w http.ResponseWriter, r *http.Request) {

	// Mint the per-instance identifier for this page load.
	// The client echoes this value on action requests and on the SSE
	// stream connect via the Datapages-Instance header.
	instanceID, err := s.signStateInstanceID()
	if err != nil {
		s.httpErrIntern(w, r, nil, "minting state instance", err)
		return
	}
	w.Header().Set(stateInstanceIDHeader, instanceID)
	// The page carries an identifier that stands for one tab's state.
	// A cache that hands it to a second visitor hands over the state.
	w.Header().Set("Cache-Control", "no-store")

	p := app.PageCount{
		App: s.app,
		Base: app.Base[app.StateCounter]{
			App: s.app,
		},
	}
	body, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageCount.GET", err)
		return
	}

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, `data-init="@get('/count/_$/')"`)
	}

	if err := s.writeHTML(
		w, r, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.logErr("rendering PageCount", err)
		return
	}
}

func (s *Server) handlePageCountGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}

	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	if _, live := s.lookupStateCounter(instanceID); !live && !s.stateHasCapacity() {
		w.Header().Set("Retry-After", "5")
		http.Error(w,
			http.StatusText(http.StatusServiceUnavailable),
			http.StatusServiceUnavailable)
		return
	}
	stateID := s.stateRouteKey(instanceID)
	var slot *stateSlotStateCounter

	p := app.PageCount{
		App: s.app,
		Base: app.Base[app.StateCounter]{
			App: s.app,
		},
	}
	s.handleStreamRequest(w, r, evSubjPageCount(stateID),
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator,
		) error {
			if existing, ok := s.reconnectStateCounter(instanceID, streamID); ok {
				slot = existing
			} else {
				slot = s.allocateStateCounter(instanceID, streamID)
			}
			// A stream that gets no slot never opens: the event loop and the
			// close hook run only once this hook has returned nil,
			// which is why neither of them checks again.
			if slot == nil {
				return errStateAtCapacity
			}
			// The close hook is wired up only once this one has returned nil.
			// An open that ends any other way hands the instance to the grace
			// timer here, since nothing else is left to give it back.
			opened := false
			defer func() {
				if !opened {
					s.closeStreamStateCounter(instanceID, streamID)
				}
			}()
			slot.mu.Lock()
			defer slot.mu.Unlock()
			if err := p.StreamOpen(r, streamID, slot.state); err != nil {
				return err
			}
			opened = true
			return nil
		},
		func(streamID uint64) {
			s.closeStreamStateCounter(instanceID, streamID)
		},
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch {
				case strings.HasPrefix(msg.Subject, EvSubjPrefPing):
					var e app.EventPing
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventPing JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnPing(e, sse, slot.state); err != nil {
						s.logErr("handling PageCount.OnPing", err)
					}
					slot.mu.Unlock()
				}
			}
		})
}

func (s *Server) handlePageCountPOSTBump(
	w http.ResponseWriter, r *http.Request,
) {
	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	slot, ok := s.lookupStateCounter(instanceID)
	if !ok {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	stateID := s.stateRouteKey(instanceID)
	slot.mu.Lock()
	defer slot.mu.Unlock()
	if slot.dead {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}

	dispatch := func(
		e1 app.EventPing,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventPing JSON: %w", err)
			}
			p0 := e1.SubjectStateID
			subj := "ping." + p0
			err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, subj, j)
			if err != nil {
				return fmt.Errorf("publishing subject %q: %w", subj, err)
			}
		}
		return nil
	}
	p := app.PageCount{
		App: s.app,
		Base: app.Base[app.StateCounter]{
			App: s.app,
		},
	}
	err := p.POSTBump(r, slot.state, stateID, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageCount.Bump", err)
		return
	}
}

